-- Esquema para correr PuntoPyme en local rápido (equivale al modelo de EF Core).
-- Docker lo ejecuta solo la primera vez que se crea el contenedor.
-- Si usan migraciones de EF (dotnet ef database update) NO usen este archivo en la misma base.

CREATE TABLE "Roles" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(30) NOT NULL
);
CREATE UNIQUE INDEX "IX_Roles_Nombre" ON "Roles" ("Nombre");
INSERT INTO "Roles" ("Id", "Nombre") OVERRIDING SYSTEM VALUE VALUES (1, 'Administrador'), (2, 'Cajero');
SELECT setval(pg_get_serial_sequence('"Roles"', 'Id'), 2);

CREATE TABLE "Usuarios" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "NombreCompleto" varchar(150) NOT NULL,
  "NombreUsuario" varchar(50) NOT NULL,
  "PinHash" varchar(200) NOT NULL,
  "RolId" integer NOT NULL REFERENCES "Roles" ("Id") ON DELETE RESTRICT,
  "Activo" boolean NOT NULL DEFAULT true,
  "IntentosFallidos" integer NOT NULL DEFAULT 0,
  "BloqueadoHastaUtc" timestamp with time zone NULL,
  "FechaCreacionUtc" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX "IX_Usuarios_NombreUsuario" ON "Usuarios" ("NombreUsuario");
CREATE INDEX "IX_Usuarios_RolId" ON "Usuarios" ("RolId");

CREATE TABLE "Productos" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(150) NOT NULL,
  "Sku" varchar(50) NOT NULL,
  "Categoria" varchar(100) NULL,
  "PrecioVenta" numeric(12,2) NOT NULL,
  "CostoCompra" numeric(12,2) NOT NULL,
  "Stock" integer NOT NULL,
  "StockMinimo" integer NOT NULL DEFAULT 5,
  CONSTRAINT "CK_Productos_PrecioVenta_MayorOIgualCosto" CHECK ("PrecioVenta" >= "CostoCompra"),
  CONSTRAINT "CK_Productos_Stock_NoNegativo" CHECK ("Stock" >= 0),
  CONSTRAINT "CK_Productos_StockMinimo_NoNegativo" CHECK ("StockMinimo" >= 0)
);
CREATE UNIQUE INDEX "IX_Productos_Sku" ON "Productos" ("Sku");

CREATE TABLE "Ventas" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdLocal" uuid NOT NULL,
  "FechaVentaUtc" timestamp with time zone NOT NULL,
  "FechaRegistroUtc" timestamp with time zone NOT NULL,
  "UsuarioId" integer NOT NULL REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT,
  "MetodoPago" varchar(20) NOT NULL,
  "Total" numeric(12,2) NOT NULL,
  "MontoRecibido" numeric(12,2) NULL,
  "Cambio" numeric(12,2) NULL,
  CONSTRAINT "CK_Ventas_MetodoPago" CHECK ("MetodoPago" IN ('Efectivo', 'Tarjeta')),
  CONSTRAINT "CK_Ventas_Total_NoNegativo" CHECK ("Total" >= 0)
);
CREATE UNIQUE INDEX "IX_Ventas_IdLocal" ON "Ventas" ("IdLocal");
CREATE INDEX "IX_Ventas_FechaVentaUtc" ON "Ventas" ("FechaVentaUtc");
CREATE INDEX "IX_Ventas_UsuarioId" ON "Ventas" ("UsuarioId");

CREATE TABLE "VentaDetalles" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "VentaId" integer NOT NULL REFERENCES "Ventas" ("Id") ON DELETE CASCADE,
  "ProductoId" integer NOT NULL REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
  "Cantidad" integer NOT NULL,
  "PrecioUnitario" numeric(12,2) NOT NULL,
  "Subtotal" numeric(12,2) NOT NULL,
  CONSTRAINT "CK_VentaDetalles_Cantidad" CHECK ("Cantidad" > 0),
  CONSTRAINT "CK_VentaDetalles_PrecioUnitario" CHECK ("PrecioUnitario" >= 0)
);
CREATE INDEX "IX_VentaDetalles_VentaId" ON "VentaDetalles" ("VentaId");
CREATE INDEX "IX_VentaDetalles_ProductoId" ON "VentaDetalles" ("ProductoId");
